toolArgs.file_text:
@namespace sv_4ed1ff62660f403f8fed20850071466e.Components.Chat
@inject IJSRuntime JS
@implements IAsyncDisposable

<div class="message-area">
    <div class="area-header">
        @if (Channel is not null)
        {
            <h2># @Channel.Name</h2>
            <span class="area-header-desc">@Channel.Description</span>
        }
    </div>

    <div class="message-list" @ref="_messageListRef" @onscroll="HandleScroll">
        @if (_loadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var msg in Messages)
        {
            <ChatMessage Message="msg"
                         ReplyCount="GetReplyCount(msg.Id)"
                         OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                         OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
        }
    </div>

    <div class="message-input-area">
        <textarea class="message-input" rows="2"
                  placeholder="@($"Message #{Channel?.Name ?? "channel"}")"
                  @bind="NewMessageText"
                  @onkeydown="HandleKeyDown" />
        <button class="send-btn" disabled="@string.IsNullOrWhiteSpace(NewMessageText)" @onclick="SendMessage">
            Send
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = [];
    [Parameter] public bool HasMoreMessages { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private string NewMessageText { get; set; } = "";
    private ElementReference _messageListRef;
    private bool _loadingMore;
    private IJSObjectReference? _module;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv_4ed1ff62660f403f8fed20850071466e/Components/Chat/MessageArea.razor.js");
        }
    }

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        if (!HasMoreMessages || _loadingMore || _module is null) return;

        var scrollTop = await _module.InvokeAsync<double>("getScrollTop", _messageListRef);
        if (scrollTop < 50)
        {
            _loadingMore = true;
            await OnLoadMore.InvokeAsync();
            _loadingMore = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessage();
        }
    }

    private async Task SendMessage()
    {
        var text = NewMessageText?.Trim();
        if (string.IsNullOrEmpty(text)) return;
        NewMessageText = "";
        await OnSendMessage.InvokeAsync(text);

        if (_module is not null)
        {
            await _module.InvokeVoidAsync("scrollToBottom", _messageListRef);
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_module is not null)
        {
            await _module.DisposeAsync();
        }
    }
}

