.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: white;
}

.area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1d1c1d;
}

.area-header-desc {
    font-size: 0.8rem;
    color: #616061;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
}

.loading-indicator {
    text-align: center;
    padding: 12px;
    font-size: 0.85rem;
    color: #616061;
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e0e0e0;
    flex-shrink: 0;
    align-items: flex-end;
}

.message-input {
    flex: 1;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    resize: none;
    outline: none;
    transition: border-color 0.15s;
}

.message-input:focus {
    border-color: #1264a3;
}

.send-btn {
    background: #007a5a;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 8px 20px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background: #005e45;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

