.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background: white;
    border-left: 1px solid #e0e0e0;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
    color: #1d1c1d;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    color: #616061;
    line-height: 1;
}

.close-btn:hover {
    background: #f0f0f0;
    color: #1d1c1d;
}

.thread-root {
    padding: 12px 16px;
    background: #f8f9fa;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1d1c1d;
    margin-bottom: 4px;
}

.root-content {
    font-size: 0.85rem;
    color: #1d1c1d;
    line-height: 1.4;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.75rem;
    color: #616061;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

.thread-reply {
    padding: 8px 16px;
}

.reply-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

.reply-author {
    font-weight: 700;
    font-size: 0.85rem;
    color: #1d1c1d;
}

.reply-time {
    font-size: 0.7rem;
    color: #616061;
}

.reply-content {
    font-size: 0.85rem;
    line-height: 1.4;
    color: #1d1c1d;
}

.reply-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    flex-shrink: 0;
    align-items: flex-end;
}

.reply-input {
    flex: 1;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.85rem;
    font-family: inherit;
    resize: none;
    outline: none;
    transition: border-color 0.15s;
}

.reply-input:focus {
    border-color: #1264a3;
}

.reply-btn {
    background: #007a5a;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.15s;
}

.reply-btn:hover:not(:disabled) {
    background: #005e45;
}

.reply-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

